import re

_PAIR = ("detail", "init", "cond", "valid", "ex", "open", "demo_ok", "chk")


def F(no, ja, sel, kind, trig="view", **kw):
    d = {"no": no, "ja": ja, "vi": "", "sel": sel, "kind": kind, "trig": trig}
    for k, v in kw.items():
        if k in _PAIR and isinstance(v, str):
            v = [v, ""]
        d[k] = v
    if isinstance(d.get("len"), str) and d["len"] and not re.match(r"^文字列 \d+$", d["len"]):
        d["len"] = [d["len"], ""]
    return d


