# ------------------------------------------------------------------ 項目の部品（詳細と編集で同じ項目を使う）
def f_item(no, f, mode):
    """f の辞書 → 詳細（表示だけ）か編集（入力）の1項目"""
    sel = f.get("sel") or 'label::%s^' % f["label"]
    if f["kind"] == "button":
        kw = {k: f[k] for k in ("len", "err", "cond", "detail", "demo_ok") if f.get(k)}
        return F(no, f["ja"], sel, "button", "click", **kw)
    if mode == "detail" or f["kind"] == "label":
        kw = {k: f[k] for k in ("len", "detail", "open", "ask") if f.get(k)}
        if mode == "detail" and f.get("demo_ok_d"):
            kw["demo_ok"] = f["demo_ok_d"]
        elif mode == "edit" and f.get("demo_ok_e"):
            kw["demo_ok"] = f["demo_ok_e"]
        elif mode == "edit" and f["kind"] == "label" and f.get("demo_ok"):
            kw["demo_ok"] = f["demo_ok"]
        return F(no, f["ja"], sel, "label", **kw)
    kw = {k: f[k] for k in ("req", "len", "ex", "valid", "cond", "err", "detail", "demo_ok", "open") if k in f}
    kw["init"] = f.get("init", "保存済みの値")
    return F(no, f["ja"], sel, f["kind"], f.get("trig", "input"), **kw)


def group(no, ja, sel, fields, mode, **kw):
    out = [F(str(no), ja, sel, "area", **kw)]
    for i, f in enumerate(fields, 1):
        out.append(f_item("%s.%d" % (no, i), f, mode))
    return out


def L(label, ja=None, **kw):
    d = {"label": label, "ja": ja or label.replace("（請求書に載る住所）", "").replace("（法人ID）", "")}
    d.update(kw)
    return d


