def _acct_dialog(no, title, q, s, okname, who):
    return [
        F(str(no), "確認ダイアログ（%s）" % title, "[role=dialog]", "modal", "show", err=[q], detail="タイトル（%sしますか？）／本文（結果どうなるか）。" % title.replace("の確認", "")),
        F("%d.1" % no, "本文", "[role=dialog] p", "label", detail=("%s の文言。対象の法人ID・%s を差し込む。" % (q, who)) if who else ("%s の文言。対象の法人ID を差し込む。" % q)),
        F("%d.2" % no, "キャンセル", "[role=dialog] button::キャンセル", "button", "click", detail="閉じる。何もしない。"),
        F("%d.3" % no, okname, "[role=dialog] button.act", "button", "click", err=[s], detail="実行して閉じ、%s のトーストを出す。変更履歴に残る。" % s),
    ]


