def _csv_cols():
    """AW_CORP_003 の入力項目（BASIC・ADDR・BILL の順）を、CSV の列の定義（項目 2.2〜）にする"""
    out = []
    k = 1
    for src, prefix in ((BASIC, "2"), (ADDR, "3"), (BILL, "6")):
        for i, f in enumerate(src, 1):
            if f["kind"] in ("label", "button"):
                continue
            k += 1
            kw = {"req": "－", "len": f.get("len", ""), "init": CSV_INIT, "ex": f["ex"], "valid": CSV_BLANK_FB if f.get("fb") else (CSV_BLANK_CHK if f["kind"] == "check" else (CSV_BLANK_REQ if f["req"] == "○" else (CSV_BLANK_COND if f["req"] == "条件付き" else CSV_BLANK_OPT))),
                  "detail": "AW_CORP_003 の項目 %s.%d「%s」と同じ（必須・桁数・チェックも同じ）。" % (prefix, i, f["ja"])}
            if f.get("err"):
                kw["err"] = ["W102" if e == "W101" else e for e in f["err"]]
            if f["req"] == "○" and "E01" not in kw.get("err", []):
                kw["err"] = ["E01"] + list(kw.get("err", []))
            if f.get("cond"):
                kw["cond"] = f["cond"]
                if f["cond"] == BILLCOND:
                    kw["valid"] = CSV_BLANK_COND + "この列に値を入れた行で、その法人のどの拠点の請求先も「法人」でないとき（全拠点が「この拠点」）は E109（その行は取り込まない）。"
                    kw["err"] = list(kw.get("err", [])) + ["E109"]
                elif f["kind"] != "check" and "のときだけ入力できる" in f["cond"]:
                    kw["valid"] = CSV_BLANK_COND + "この列に値を入れた行で条件（" + f["cond"] + "）に当てはまらないときは E109（その行は取り込まない）。"
                    kw["err"] = list(kw.get("err", [])) + ["E109"]
            out.append(F("2.%d" % k, f["ja"], "-", f["kind"], "input", **kw))
    return out


